import { ChangeEvent, FormEvent, ReactNode, useEffect, useMemo, useRef, useState } from 'react'
import { hrxSupabase } from './supabaseClient'
import { navigateAdmin, onAdminNavigate, type AdminDestination } from './adminNavigation'
import { passwordMeetsPolicy, passwordRequirementText, secureUpdateAdminPassword } from './passwordSecurity'
import AdminClientForm from './AdminClientForm'

type PrimaryView = 'executive' | 'panels' | 'activities' | 'clients' | 'documents' | 'settings'
type IconName = 'home' | 'briefcase' | 'check' | 'users' | 'file' | 'settings' | 'search' | 'bell' | 'chevron' | 'warning' | 'clock' | 'calendar' | 'filter' | 'plus' | 'more' | 'eye' | 'download' | 'share' | 'lock' | 'logout'
type ClientRow = { id: string; created_at: string; updated_at: string; name: string; company?: string | null; email?: string | null; phone?: string | null; document?: string | null; notes?: string | null; source: string; active: boolean; last_quote_at?: string | null }
type RequestRow = { id: string; client_id?: string | null; protocol: string; created_at: string; name: string; company?: string | null; email?: string | null; request_text?: string | null; desired_deadline?: string | null; source?: string | null }
type DraftRow = { request_id: string; status: string; final_amount?: number | null; updated_at?: string | null; suspension_reason?: string | null; suspension_note?: string | null }
type DocumentRow = { id: string; object_path: string; area_key: string; folder: string; client_name?: string | null; document_type?: string | null; title: string; version: number; status: 'active' | 'superseded' | 'archived'; access_class: 'internal' | 'restricted' | 'confidential'; expires_at?: string | null; mime_type?: string | null; size_bytes?: number | null; created_at: string; updated_at?: string | null }
type ProjectRow = RequestRow & { draft?: DraftRow | null; status: string; progress: number | null; priority: 'Alta' | 'Média' | 'Baixa'; milestone: string }
type ActivityRow = { id: string; title: string; context: string; kind: 'document' | 'project'; status: 'progress' | 'blocked' | 'validation' | 'complete'; priority: 'Alta' | 'Média' | 'Baixa'; at: string; detail?: string }

const areaLabels: Record<string, string> = { institutional: 'Institucional', clients: 'Clientes', templates: 'Modelos', internal: 'Projetos', commercial: 'Comercial', finance: 'Financeiro', legal: 'Contratos', archive: 'Arquivo' }
const categoryOptions = [['clients', 'Clientes'], ['internal', 'Projetos'], ['commercial', 'Comercial'], ['templates', 'Modelos'], ['finance', 'Financeiro'], ['legal', 'Contratos'], ['institutional', 'Institucional'], ['archive', 'Arquivo']] as const
const statusLabels: Record<string, string> = { new: 'Novo', received: 'Em andamento', awaiting_review: 'Em validação', needs_scope: 'Atenção', approved: 'Concluído', rejected: 'Encerrado', suspended: 'Bloqueado' }
const statusTone: Record<string, string> = { new: 'info', received: 'info', awaiting_review: 'review', needs_scope: 'warning', approved: 'success', rejected: 'danger', suspended: 'danger', active: 'success', superseded: 'warning', archived: 'muted' }
const statusProgress: Record<string, number | null> = { new: null, received: null, awaiting_review: null, needs_scope: null, approved: 100, rejected: 100, suspended: null }
const statusMilestone: Record<string, string> = { new: 'Triagem inicial', received: 'Análise da solicitação', awaiting_review: 'Validação administrativa', needs_scope: 'Completar escopo', approved: 'Entrega aprovada', rejected: 'Registro encerrado', suspended: 'Resolver bloqueio' }

function Icon({ name, size = 20 }: { name: IconName; size?: number }) {
  const common = { fill: 'none', stroke: 'currentColor', strokeWidth: 1.8, strokeLinecap: 'round' as const, strokeLinejoin: 'round' as const }
  const paths: Record<IconName, ReactNode> = {
    home: <><path d="m3 10 9-7 9 7"/><path d="M5 9v11h14V9M9 20v-7h6v7"/></>, briefcase: <><rect x="3" y="7" width="18" height="13" rx="2"/><path d="M8 7V4h8v3M3 12h18M10 12v2h4v-2"/></>,
    check: <><circle cx="12" cy="12" r="9"/><path d="m8 12 2.5 2.5L16 9"/></>, users: <><path d="M16 21v-2a4 4 0 0 0-4-4H6a4 4 0 0 0-4 4v2"/><circle cx="9" cy="7" r="4"/><path d="M22 21v-2a4 4 0 0 0-3-3.87M16 3.13a4 4 0 0 1 0 7.75"/></>,
    file: <><path d="M14 2H6a2 2 0 0 0-2 2v16a2 2 0 0 0 2 2h12a2 2 0 0 0 2-2V8z"/><path d="M14 2v6h6M8 13h8M8 17h6"/></>, settings: <><circle cx="12" cy="12" r="3"/><path d="M19.4 15a1.7 1.7 0 0 0 .34 1.88l-2.83 2.83A1.7 1.7 0 0 0 15 19.37a1.7 1.7 0 0 0-1 1.55V21h-4a1.7 1.7 0 0 0-1-1.63 1.7 1.7 0 0 0-1.88.34l-2.83-2.83A1.7 1.7 0 0 0 4.63 15a1.7 1.7 0 0 0-1.55-1H3v-4a1.7 1.7 0 0 0 1.63-1 1.7 1.7 0 0 0-.34-1.88l2.83-2.83A1.7 1.7 0 0 0 9 4.63a1.7 1.7 0 0 0 1-1.55V3h4a1.7 1.7 0 0 0 1 1.63 1.7 1.7 0 0 0 1.88-.34l2.83 2.83A1.7 1.7 0 0 0 19.37 9a1.7 1.7 0 0 0 1.55 1H21v4a1.7 1.7 0 0 0-1.6 1Z"/></>,
    search: <><circle cx="11" cy="11" r="7"/><path d="m20 20-4-4"/></>, bell: <><path d="M18 8a6 6 0 0 0-12 0c0 7-3 7-3 9h18c0-2-3-2-3-9"/><path d="M10 21h4"/></>, chevron: <path d="m9 18 6-6-6-6"/>,
    warning: <><path d="M10.3 2.9 1.8 17a2 2 0 0 0 1.7 3h17a2 2 0 0 0 1.7-3L13.7 2.9a2 2 0 0 0-3.4 0Z"/><path d="M12 9v4M12 17h.01"/></>, clock: <><circle cx="12" cy="12" r="9"/><path d="M12 7v5l3 2"/></>, calendar: <><rect x="3" y="5" width="18" height="16" rx="2"/><path d="M16 3v4M8 3v4M3 10h18"/></>,
    filter: <path d="M4 5h16l-6 7v5l-4 2v-7Z"/>, plus: <path d="M12 5v14M5 12h14"/>, more: <><circle cx="5" cy="12" r="1" fill="currentColor"/><circle cx="12" cy="12" r="1" fill="currentColor"/><circle cx="19" cy="12" r="1" fill="currentColor"/></>,
    eye: <><path d="M2 12s3.5-6 10-6 10 6 10 6-3.5 6-10 6S2 12 2 12Z"/><circle cx="12" cy="12" r="2.5"/></>, download: <><path d="M12 3v12M7 10l5 5 5-5M5 21h14"/></>, share: <><circle cx="18" cy="5" r="2"/><circle cx="6" cy="12" r="2"/><circle cx="18" cy="19" r="2"/><path d="m8 11 8-5M8 13l8 5"/></>,
    lock: <><rect x="4" y="10" width="16" height="11" rx="2"/><path d="M8 10V7a4 4 0 0 1 8 0v3"/></>, logout: <><path d="M10 17l5-5-5-5M15 12H3M21 19V5a2 2 0 0 0-2-2h-6"/></>,
  }
  return <svg aria-hidden="true" viewBox="0 0 24 24" width={size} height={size} {...common}>{paths[name]}</svg>
}

function formatDate(value?: string | null, withTime = false) { if (!value) return 'Não informado'; const date = new Date(value); if (Number.isNaN(date.valueOf())) return value; return date.toLocaleString('pt-BR', withTime ? { dateStyle: 'short', timeStyle: 'short' } : { dateStyle: 'short' }) }
function formatBytes(value?: number | null) { const bytes = Number(value ?? 0); if (!bytes) return 'Tamanho não informado'; if (bytes < 1024) return `${bytes} B`; if (bytes < 1024 * 1024) return `${(bytes / 1024).toFixed(1)} KB`; return `${(bytes / 1024 / 1024).toFixed(1)} MB` }
function isRecent(value: string, days = 7) { return Date.now() - new Date(value).valueOf() <= days * 86400000 }
function sameDay(value: string) { return new Date(value).toDateString() === new Date().toDateString() }
function thisWeek(value: string) { const age = Date.now() - new Date(value).valueOf(); return age >= 0 && age <= 7 * 86400000 }
function Badge({ status, label }: { status: string; label?: string }) { return <span className={`hrx-status tone-${statusTone[status] ?? status}`}>{label ?? statusLabels[status] ?? status.replaceAll('_', ' ')}</span> }
function MetricCard({ icon, label, value, tone, note }: { icon: IconName; label: string; value: number; tone: string; note: string }) { return <article className={`hrx-glass-metric tone-${tone}`}><span className="hrx-glass-icon"><Icon name={icon}/></span><div><small>{label}</small><strong>{value.toLocaleString('pt-BR')}</strong><p>{note}</p></div></article> }

export default function AdminExperienceLayer() {
  const preview = import.meta.env.DEV && new URLSearchParams(window.location.search).get('hrx-preview') === '1'
  const initialHash = window.location.hash.replace('#admin/', '')
  const initialView: AdminDestination = initialHash === 'painels' ? 'panels' : initialHash === 'atividades' ? 'activities' : initialHash === 'clientes' ? 'clients' : initialHash === 'documentos' ? 'documents' : initialHash === 'configuracoes' ? 'settings' : 'executive'
  const [active, setActive] = useState<AdminDestination>(initialView)
  const [collapsed, setCollapsed] = useState(false)
  const [loading, setLoading] = useState(true)
  const [error, setError] = useState('')
  const [clients, setClients] = useState<ClientRow[]>([])
  const [requests, setRequests] = useState<RequestRow[]>([])
  const [drafts, setDrafts] = useState<DraftRow[]>([])
  const [documents, setDocuments] = useState<DocumentRow[]>([])
  const [userName, setUserName] = useState('Administrador HRX')
  const [userRole, setUserRole] = useState('Administrador')
  const [email, setEmail] = useState('')
  const [globalQuery, setGlobalQuery] = useState('')
  const [query, setQuery] = useState('')
  const [statusFilter, setStatusFilter] = useState('all')
  const [priorityFilter, setPriorityFilter] = useState('all')
  const [clientFilter, setClientFilter] = useState('all')
  const [categoryFilter, setCategoryFilter] = useState('all')
  const [activityTab, setActivityTab] = useState('all')
  const [selectedProject, setSelectedProject] = useState<ProjectRow | null>(null)
  const [selectedClient, setSelectedClient] = useState<ClientRow | null>(null)
  const [selectedDocument, setSelectedDocument] = useState<DocumentRow | null>(null)
  const [accountOpen, setAccountOpen] = useState(false)
  const [clientFormOpen, setClientFormOpen] = useState(false)
  const [quoteFormOpen, setQuoteFormOpen] = useState(false)
  const [quoteClientId, setQuoteClientId] = useState('')
  const [quoteScope, setQuoteScope] = useState('')
  const [quoteBusy, setQuoteBusy] = useState(false)
  const [uploading, setUploading] = useState(false)
  const [password, setPassword] = useState('')
  const [confirmPassword, setConfirmPassword] = useState('')
  const [passwordBusy, setPasswordBusy] = useState(false)
  const [passwordMessage, setPasswordMessage] = useState('')
  const fileInput = useRef<HTMLInputElement>(null)

  const load = async () => {
    if (preview) { setLoading(false); return }
    setLoading(true); setError('')
    try {
      const [{ data: userData }, clientsResult, requestsResult, draftsResult, documentsResult] = await Promise.all([
        hrxSupabase.auth.getUser(),
        hrxSupabase.from('clients').select('id,created_at,updated_at,name,company,email,phone,document,notes,source,active,last_quote_at').order('name'),
        hrxSupabase.from('quote_requests').select('id,client_id,protocol,created_at,name,company,email,request_text,desired_deadline,source').order('created_at', { ascending: false }).limit(500),
        hrxSupabase.from('quote_drafts').select('request_id,status,final_amount,updated_at,suspension_reason,suspension_note'),
        hrxSupabase.from('hrx_documents').select('*').neq('status', 'archived').order('created_at', { ascending: false }).limit(1000),
      ])
      if (clientsResult.error || requestsResult.error || draftsResult.error || documentsResult.error) throw new Error('data_unavailable')
      const user = userData.user; const metadata = user?.user_metadata ?? {}
      setEmail(user?.email ?? ''); setUserName(metadata.full_name || metadata.name || user?.email?.split('@')[0] || 'Administrador HRX'); setUserRole(metadata.role || 'Administrador')
      setClients((clientsResult.data ?? []) as ClientRow[]); setRequests((requestsResult.data ?? []) as RequestRow[]); setDrafts((draftsResult.data ?? []) as DraftRow[]); setDocuments((documentsResult.data ?? []) as DocumentRow[])
    } catch { setError('Não foi possível atualizar todos os dados do painel. Tente novamente.') } finally { setLoading(false) }
  }

  useEffect(() => { void load() }, [])
  useEffect(() => onAdminNavigate((destination) => { setActive(destination); setAccountOpen(false); setQuery(''); setGlobalQuery('') }), [])
  useEffect(() => { setSelectedProject(null); setSelectedClient(null); setSelectedDocument(null) }, [active])
  const draftMap = useMemo(() => new Map(drafts.map((draft) => [draft.request_id, draft])), [drafts])
  const projects = useMemo<ProjectRow[]>(() => requests.map((request) => { const draft = draftMap.get(request.id) ?? null; const status = draft?.status ?? 'received'; return { ...request, draft, status, progress: statusProgress[status] ?? null, priority: status === 'suspended' || status === 'needs_scope' ? 'Alta' : status === 'awaiting_review' ? 'Média' : 'Baixa', milestone: statusMilestone[status] ?? 'Acompanhamento' } }), [requests, draftMap])
  const activities = useMemo<ActivityRow[]>(() => {
    const requestActivities = projects.map((project) => ({ id: `request-${project.id}`, title: project.milestone, context: `${project.protocol} · ${project.company || project.name}`, kind: 'project' as const, status: project.status === 'suspended' ? 'blocked' as const : project.status === 'awaiting_review' ? 'validation' as const : ['approved', 'rejected'].includes(project.status) ? 'complete' as const : 'progress' as const, priority: project.priority, at: project.draft?.updated_at || project.created_at, detail: project.draft?.suspension_reason || project.draft?.suspension_note || undefined }))
    const documentActivities = documents.map((document) => ({ id: `document-${document.id}`, title: 'Documento atualizado', context: `${document.title} · ${document.client_name || areaLabels[document.area_key] || document.area_key}`, kind: 'document' as const, status: 'complete' as const, priority: 'Baixa' as const, at: document.updated_at || document.created_at }))
    return [...requestActivities, ...documentActivities].sort((a, b) => +new Date(b.at) - +new Date(a.at))
  }, [projects, documents])

  const activeProjects = projects.filter((item) => !['approved', 'rejected'].includes(item.status)); const blocked = projects.filter((item) => item.status === 'suspended'); const completed = projects.filter((item) => ['approved', 'rejected'].includes(item.status)); const recentDocuments = documents.filter((item) => isRecent(item.updated_at || item.created_at))
  const notificationCount = blocked.length + documents.filter((item) => item.expires_at && new Date(item.expires_at) < new Date()).length
  const initials = userName.split(/\s+/).filter(Boolean).slice(0, 2).map((part) => part[0]).join('').toUpperCase() || 'HR'
  const searchTerm = `${query} ${globalQuery}`.trim().toLocaleLowerCase('pt-BR')
  const visibleProjects = projects.filter((project) => (!searchTerm || [project.protocol, project.name, project.company, project.request_text].some((value) => value?.toLocaleLowerCase('pt-BR').includes(searchTerm))) && (statusFilter === 'all' || project.status === statusFilter) && (priorityFilter === 'all' || project.priority === priorityFilter) && (clientFilter === 'all' || project.client_id === clientFilter))
  const visibleClients = clients.filter((client) => !searchTerm || [client.name, client.company, client.email, client.phone, client.document].some((value) => value?.toLocaleLowerCase('pt-BR').includes(searchTerm)))
  const visibleDocuments = documents.filter((document) => (!searchTerm || [document.title, document.client_name, document.folder, document.document_type].some((value) => value?.toLocaleLowerCase('pt-BR').includes(searchTerm))) && (statusFilter === 'all' || document.status === statusFilter) && (categoryFilter === 'all' || document.area_key === categoryFilter) && (clientFilter === 'all' || document.client_name === clients.find((item) => item.id === clientFilter)?.name))
  const visibleActivities = activities.filter((item) => activityTab === 'all' || item.status === activityTab)
  const searchResults = useMemo(() => { const term = globalQuery.trim().toLocaleLowerCase('pt-BR'); if (term.length < 2) return []; return [...projects.filter((item) => [item.protocol, item.company, item.name].some((value) => value?.toLocaleLowerCase('pt-BR').includes(term))).slice(0, 3).map((item) => ({ id: item.id, view: 'panels' as PrimaryView, label: item.protocol, meta: item.company || item.name })), ...clients.filter((item) => [item.name, item.company].some((value) => value?.toLocaleLowerCase('pt-BR').includes(term))).slice(0, 3).map((item) => ({ id: item.id, view: 'clients' as PrimaryView, label: item.company || item.name, meta: item.email || 'Cliente' })), ...documents.filter((item) => item.title.toLocaleLowerCase('pt-BR').includes(term)).slice(0, 3).map((item) => ({ id: item.id, view: 'documents' as PrimaryView, label: item.title, meta: item.folder }))].slice(0, 7) }, [globalQuery, projects, clients, documents])

  const go = (destination: PrimaryView) => { setActive(destination); setQuery(''); setGlobalQuery(''); const hash = { executive: 'visao-geral', panels: 'painels', activities: 'atividades', clients: 'clientes', documents: 'documentos', settings: 'configuracoes' }[destination]; history.replaceState(null, '', `${window.location.pathname}#admin/${hash}`) }
  const openCommercial = () => navigateAdmin('quotes')
  const openDocument = async (document: DocumentRow, download = false) => { if (document.object_path.startsWith('external:')) { window.open(document.object_path.slice(9), '_blank', 'noopener,noreferrer'); return } const { data, error: signedError } = await hrxSupabase.storage.from('hrx-documents').createSignedUrl(document.object_path, 60, download ? { download: true } : undefined); if (signedError || !data?.signedUrl) { setError('Não foi possível gerar o acesso temporário ao documento.'); return } window.open(data.signedUrl, '_blank', 'noopener,noreferrer') }
  const shareDocument = async (document: DocumentRow) => { if (!navigator.share) return; const { data } = document.object_path.startsWith('external:') ? { data: { signedUrl: document.object_path.slice(9) } } : await hrxSupabase.storage.from('hrx-documents').createSignedUrl(document.object_path, 60); if (data?.signedUrl) await navigator.share({ title: document.title, url: data.signedUrl }).catch(() => undefined) }
  const uploadDocument = async (event: ChangeEvent<HTMLInputElement>) => { const file = event.target.files?.[0]; event.target.value = ''; if (!file || uploading) return; if (file.size > 25 * 1024 * 1024) { setError('O arquivo excede o limite de 25 MB.'); return } const areaKey = categoryFilter !== 'all' ? categoryFilter : 'institutional'; const folder = areaLabels[areaKey] || 'Geral'; const safeName = file.name.normalize('NFD').replace(/[\u0300-\u036f]/g, '').replace(/[^A-Za-z0-9_.-]+/g, '_'); const objectPath = `${areaKey}/geral/${Date.now()}_${safeName}`; setUploading(true); setError(''); const { error: uploadError } = await hrxSupabase.storage.from('hrx-documents').upload(objectPath, file, { contentType: file.type || undefined }); if (!uploadError) { const { error: metadataError } = await hrxSupabase.from('hrx_documents').insert({ object_path: objectPath, area_key: areaKey, folder, title: file.name.replace(/\.[^.]+$/, ''), document_type: file.name.split('.').pop()?.toUpperCase() || 'ARQUIVO', version: 1, status: 'active', access_class: ['legal', 'finance'].includes(areaKey) ? 'restricted' : 'internal', mime_type: file.type || null, size_bytes: file.size }); if (metadataError) { await hrxSupabase.storage.from('hrx-documents').remove([objectPath]); setError('O arquivo foi removido porque os metadados não puderam ser registrados.') } else await load() } else setError('Não foi possível enviar o documento.'); setUploading(false) }
  const createManualQuote = async (event: FormEvent) => { event.preventDefault(); if (!quoteClientId) return; setQuoteBusy(true); setError(''); const { error: quoteError } = await hrxSupabase.rpc('hrx_create_manual_quote', { p_client_id: quoteClientId, p_request_text: quoteScope || null, p_desired_deadline: null, p_preferred_contact: 'whatsapp' }); setQuoteBusy(false); if (quoteError) { setError('Não foi possível criar o orçamento manual.'); return } setQuoteFormOpen(false); setQuoteScope(''); openCommercial() }
  const changePassword = async (event: FormEvent) => { event.preventDefault(); if (!passwordMeetsPolicy(password) || password !== confirmPassword) return; setPasswordBusy(true); setPasswordMessage(''); const result = await secureUpdateAdminPassword(password); setPasswordBusy(false); setPasswordMessage(result.ok ? 'Senha atualizada com sucesso.' : result.message); if (result.ok) { setPassword(''); setConfirmPassword('') } }
  const navItems: Array<{ view: PrimaryView; label: string; icon: IconName }> = [{ view: 'executive', label: 'Visão Geral', icon: 'home' }, { view: 'panels', label: 'Projetos', icon: 'briefcase' }, { view: 'activities', label: 'Atividades', icon: 'check' }, { view: 'clients', label: 'Clientes', icon: 'users' }, { view: 'documents', label: 'Central de Documentos', icon: 'file' }, { view: 'settings', label: 'Configurações', icon: 'settings' }]

  if (!['executive', 'panels', 'activities', 'clients', 'documents', 'settings'].includes(active)) return <div className="hrx-legacy-shell"><button type="button" className="hrx-back-to-dashboard" onClick={() => go('executive')}>← Voltar ao painel</button></div>
  return <div className={`hrx-glass-app${collapsed ? ' is-collapsed' : ''}`}>
    <aside className="hrx-glass-sidebar" aria-label="Navegação principal do HRX Admin"><div className="hrx-glass-brand"><strong>HRX</strong><span>Solutions</span></div><nav>{navItems.map((item) => <button type="button" key={item.view} className={active === item.view ? 'is-active' : ''} onClick={() => go(item.view)} aria-current={active === item.view ? 'page' : undefined}><Icon name={item.icon}/><span>{item.label}</span></button>)}</nav><button type="button" className="hrx-collapse" onClick={() => setCollapsed((value) => !value)}><Icon name="chevron"/><span>{collapsed ? 'Expandir menu' : 'Recolher menu'}</span></button></aside>
    <header className="hrx-glass-topbar"><div className="hrx-mobile-brand"><strong>HRX</strong><span>Solutions</span></div><label className="hrx-global-search"><Icon name="search"/><input value={globalQuery} onChange={(event) => setGlobalQuery(event.target.value)} placeholder="Buscar projetos, atividades, clientes ou documentos…" aria-label="Pesquisa global"/><kbd>⌘ K</kbd>{searchResults.length > 0 && <div className="hrx-search-results">{searchResults.map((result) => <button type="button" key={`${result.view}-${result.id}`} onClick={() => { go(result.view); if (result.view === 'panels') setSelectedProject(projects.find((item) => item.id === result.id) ?? null); if (result.view === 'clients') setSelectedClient(clients.find((item) => item.id === result.id) ?? null); if (result.view === 'documents') setSelectedDocument(documents.find((item) => item.id === result.id) ?? null) }}><strong>{result.label}</strong><span>{result.meta}</span></button>)}</div>}</label><button type="button" className="hrx-notifications" aria-label={`${notificationCount} notificações`}><Icon name="bell"/>{notificationCount > 0 && <span>{notificationCount}</span>}</button><div className="hrx-account"><button type="button" onClick={() => setAccountOpen((value) => !value)} aria-expanded={accountOpen}><span className="hrx-avatar">{initials}</span><span className="hrx-account-copy"><strong>{userName}</strong><small>{userRole}</small></span><Icon name="chevron" size={16}/></button>{accountOpen && <div className="hrx-account-menu"><span>{email || 'Sessão administrativa'}</span><button type="button" onClick={() => go('settings')}><Icon name="settings" size={17}/>Configurações</button><button type="button" onClick={() => void hrxSupabase.auth.signOut()}><Icon name="logout" size={17}/>Sair</button></div>}</div></header>
    <main className="hrx-glass-main">{error && <div className="hrx-glass-alert" role="alert">{error}<button type="button" onClick={() => setError('')}>×</button></div>}{loading && <div className="hrx-loading"><span/><strong>Atualizando dados reais da operação…</strong></div>}
      {active === 'executive' && <DashboardView activeProjects={activeProjects} blocked={blocked} recentDocuments={recentDocuments} projects={projects} activities={activities} documents={documents} onGo={go} onSelectProject={(project) => { go('panels'); setSelectedProject(project) }}/>}
      {active === 'panels' && <ProjectsView projects={projects} visible={visibleProjects} clients={clients} activeProjects={activeProjects} blocked={blocked} completed={completed} selected={selectedProject} onSelect={setSelectedProject} onClose={() => setSelectedProject(null)} onOpenCommercial={openCommercial} query={query} setQuery={setQuery} statusFilter={statusFilter} setStatusFilter={setStatusFilter} priorityFilter={priorityFilter} setPriorityFilter={setPriorityFilter} clientFilter={clientFilter} setClientFilter={setClientFilter}/>}
      {active === 'activities' && <ActivitiesView activities={visibleActivities} allActivities={activities} projects={activeProjects} blocked={blocked} activityTab={activityTab} setActivityTab={setActivityTab}/>}
      {active === 'clients' && <ClientsView clients={clients} visible={visibleClients} requests={requests} selected={selectedClient} onSelect={setSelectedClient} onClose={() => setSelectedClient(null)} onNew={() => setClientFormOpen(true)} onQuote={(id) => { setQuoteClientId(id); setQuoteFormOpen(true) }} query={query} setQuery={setQuery}/>}
      {active === 'documents' && <DocumentsView documents={documents} visible={visibleDocuments} clients={clients} selected={selectedDocument} onSelect={setSelectedDocument} onClose={() => setSelectedDocument(null)} onOpen={openDocument} onShare={shareDocument} uploading={uploading} onUpload={() => fileInput.current?.click()} query={query} setQuery={setQuery} clientFilter={clientFilter} setClientFilter={setClientFilter} categoryFilter={categoryFilter} setCategoryFilter={setCategoryFilter} statusFilter={statusFilter} setStatusFilter={setStatusFilter}/>}
      {active === 'settings' && <SettingsView initials={initials} userName={userName} email={email} userRole={userRole} password={password} setPassword={setPassword} confirmPassword={confirmPassword} setConfirmPassword={setConfirmPassword} busy={passwordBusy} message={passwordMessage} onSubmit={changePassword}/>}
    </main>
    <input ref={fileInput} hidden type="file" accept=".pdf,.docx,.xlsx,.pptx,.txt,.csv,.png,.jpg,.jpeg,.webp" onChange={(event) => void uploadDocument(event)}/>
    <nav className="hrx-mobile-nav" aria-label="Navegação mobile do HRX Admin">{navItems.filter((item) => item.view !== 'settings' && item.view !== 'clients').map((item) => <button key={item.view} className={active === item.view ? 'is-active' : ''} onClick={() => go(item.view)}><Icon name={item.icon}/><span>{item.view === 'documents' ? 'Docs' : item.label.replace('Visão Geral','Início')}</span></button>)}<button className={active === 'settings' || active === 'clients' ? 'is-active' : ''} onClick={() => go('settings')}><Icon name="users"/><span>Perfil</span></button></nav>
    {clientFormOpen && <AdminClientForm onClose={() => setClientFormOpen(false)} onCreated={async () => { setClientFormOpen(false); await load() }}/>}
    {quoteFormOpen && <div className="hrx-modal-backdrop" onMouseDown={(event) => { if (event.target === event.currentTarget) setQuoteFormOpen(false) }}><form className="hrx-modal" onSubmit={createManualQuote}><header><div><span>OPERAÇÃO COMERCIAL</span><h2>Novo orçamento</h2></div><button type="button" onClick={() => setQuoteFormOpen(false)}>×</button></header><label>Cliente<select value={quoteClientId} onChange={(event) => setQuoteClientId(event.target.value)} required><option value="">Selecione</option>{clients.filter((client) => client.active).map((client) => <option key={client.id} value={client.id}>{client.company || client.name}</option>)}</select></label><label>Escopo inicial<textarea rows={5} value={quoteScope} onChange={(event) => setQuoteScope(event.target.value)} placeholder="Descreva a demanda real do cliente."/></label><footer><button type="button" onClick={() => setQuoteFormOpen(false)}>Cancelar</button><button className="hrx-primary-button" disabled={quoteBusy || !quoteClientId}>{quoteBusy ? 'Criando…' : 'Criar orçamento'}</button></footer></form></div>}
  </div>
}

function ViewTitle({ id, title, description, children }: { id: string; title: string; description: string; children?: ReactNode }) { return <div className="hrx-view-title"><div><h1 id={id}>{title}</h1><p>{description}</p></div>{children}</div> }
function Empty({ icon, title, text, compact = false }: { icon?: IconName; title: string; text?: string; compact?: boolean }) { return <div className={`hrx-empty${compact ? ' is-compact' : ''}`}>{icon && <Icon name={icon}/>}<strong>{title}</strong>{text && <span>{text}</span>}</div> }

function DashboardView({ activeProjects, blocked, recentDocuments, projects, activities, documents, onGo, onSelectProject }: { activeProjects: ProjectRow[]; blocked: ProjectRow[]; recentDocuments: DocumentRow[]; projects: ProjectRow[]; activities: ActivityRow[]; documents: DocumentRow[]; onGo: (view: PrimaryView) => void; onSelectProject: (project: ProjectRow) => void }) {
  const attention = projects.filter((item) => ['suspended', 'needs_scope', 'awaiting_review'].includes(item.status))
  return <section className="hrx-view hrx-dashboard-view" aria-labelledby="dashboard-title"><ViewTitle id="dashboard-title" title="Painel HRX Solutions" description="Visão geral da sua operação com dados do ambiente administrativo."><time><Icon name="calendar" size={18}/>{new Date().toLocaleDateString('pt-BR', { day: '2-digit', month: 'long', year: 'numeric' })}</time></ViewTitle><div className="hrx-mobile-page-title"><h1>Início</h1><p>Visão geral da sua operação</p></div><div className="hrx-metric-grid"><MetricCard icon="briefcase" label="Projetos Ativos" value={activeProjects.length} tone="blue" note="Solicitações abertas"/><MetricCard icon="check" label="Atividades em Andamento" value={activities.filter((item) => item.status === 'progress').length} tone="green" note="Eventos reais"/><MetricCard icon="warning" label="Bloqueios" value={blocked.length} tone="orange" note="Itens suspensos"/><MetricCard icon="file" label="Documentos Atualizados" value={recentDocuments.length} tone="purple" note="Últimos 7 dias"/></div><div className="hrx-dashboard-grid"><section className="hrx-glass-panel hrx-attention-panel"><header><h2>Projetos que exigem atenção</h2><button type="button" onClick={() => onGo('panels')}>Ver todos</button></header><div className="hrx-project-head"><span>Projeto</span><span>Status</span><span>Progresso</span><span>Prazo</span></div><div className="hrx-project-list">{attention.slice(0, 5).map((project) => <button type="button" key={project.id} onClick={() => onSelectProject(project)}><span className="hrx-row-icon tone-blue"><Icon name="briefcase"/></span><span className="hrx-row-main"><strong>{project.protocol}</strong><small>{project.company || project.name}</small></span><Badge status={project.status}/><span className="hrx-progress-cell">{project.progress === null ? <small>Não informado</small> : <><b>{project.progress}%</b><i><em style={{ width: `${project.progress}%` }}/></i></>}</span><time>{project.desired_deadline || 'Sem prazo'}</time><Icon name="more" size={18}/></button>)}{!attention.length && <Empty icon="check" title="Nenhum projeto exige atenção agora." text="Os dados aparecem aqui conforme o fluxo real avança."/>}</div></section><aside className="hrx-dashboard-side"><CompactActivities activities={activities.slice(0,5)} onGo={() => onGo('activities')}/><NextSteps projects={activeProjects.slice(0,4)} onGo={() => onGo('activities')}/></aside></div><div className="hrx-mobile-sections"><MobileSection title="Atividades do dia" onGo={() => onGo('activities')}>{activities.filter((item) => sameDay(item.at)).slice(0,2).map((item) => <article className="hrx-mobile-row" key={item.id}><time>{new Date(item.at).toLocaleTimeString('pt-BR', { hour: '2-digit', minute: '2-digit' })}</time><div><strong>{item.title}</strong><small>{item.context}</small></div><Icon name="chevron"/></article>)}</MobileSection><MobileSection title="Documentos recentes" onGo={() => onGo('documents')}>{documents.slice(0,3).map((document) => <article className="hrx-mobile-row" key={document.id}><span className="hrx-row-icon tone-purple"><Icon name="file"/></span><div><strong>{document.title}</strong><small>{document.folder}</small></div><time>{formatDate(document.created_at)}</time></article>)}</MobileSection><MobileSection title="Itens bloqueados" onGo={() => onGo('activities')}>{blocked.slice(0,2).map((project) => <article className="hrx-mobile-row" key={project.id}><Badge status="suspended" label="Alto"/><div><strong>{project.milestone}</strong><small>{project.company || project.name}</small></div><time>{formatDate(project.draft?.updated_at || project.created_at)}</time></article>)}</MobileSection><MobileSection title="Atualizações recentes" onGo={() => onGo('activities')}>{activities.slice(0,3).map((item) => <article className="hrx-mobile-row" key={item.id}><span className="hrx-row-icon tone-green"><Icon name="check"/></span><div><strong>{item.title}</strong><small>{item.context}</small></div><time>{formatDate(item.at)}</time></article>)}</MobileSection></div></section>
}
function CompactActivities({ activities, onGo }: { activities: ActivityRow[]; onGo: () => void }) { return <section className="hrx-glass-panel"><header><h2>Atividades recentes</h2><button type="button" onClick={onGo}>Ver todas</button></header><div className="hrx-compact-list">{activities.map((item) => <article key={item.id}><span className={`hrx-row-icon tone-${item.kind === 'document' ? 'purple' : item.status === 'blocked' ? 'orange' : 'blue'}`}><Icon name={item.kind === 'document' ? 'file' : item.status === 'blocked' ? 'warning' : 'check'} size={17}/></span><div><strong>{item.title}</strong><small>{item.context}</small></div><time>{formatDate(item.at, true)}</time></article>)}{!activities.length && <Empty title="Nenhuma atividade registrada." compact/>}</div></section> }
function NextSteps({ projects }: { projects: ProjectRow[]; onGo?: () => void }) { return <section className="hrx-glass-panel"><header><h2>Próximos passos</h2></header><div className="hrx-next-list">{projects.map((project) => <article key={project.id}><span/><div><strong>{project.milestone}</strong><small>{project.company || project.name}</small></div><time>{project.desired_deadline || 'Sem prazo'}</time></article>)}{!projects.length && <Empty title="Nenhum próximo passo aberto." compact/>}</div></section> }
function MobileSection({ title, onGo, children }: { title: string; onGo: () => void; children: ReactNode }) { return <section className="hrx-glass-panel"><header><h2>{title}</h2><button onClick={onGo}>Ver todos</button></header>{children}</section> }

function ProjectsView({ projects, visible, clients, activeProjects, blocked, completed, selected, onSelect, onClose, onOpenCommercial, query, setQuery, statusFilter, setStatusFilter, priorityFilter, setPriorityFilter, clientFilter, setClientFilter }: { projects: ProjectRow[]; visible: ProjectRow[]; clients: ClientRow[]; activeProjects: ProjectRow[]; blocked: ProjectRow[]; completed: ProjectRow[]; selected: ProjectRow | null; onSelect: (item: ProjectRow) => void; onClose: () => void; onOpenCommercial: () => void; query: string; setQuery: (value: string) => void; statusFilter: string; setStatusFilter: (value: string) => void; priorityFilter: string; setPriorityFilter: (value: string) => void; clientFilter: string; setClientFilter: (value: string) => void }) {
  return <section className={`hrx-view hrx-table-view${selected ? ' has-drawer' : ''}`} aria-labelledby="projects-title"><ViewTitle id="projects-title" title="Projetos" description="Acompanhamento derivado das solicitações reais registradas na operação."><button className="hrx-primary-button" type="button" onClick={onOpenCommercial}><Icon name="plus"/>Novo orçamento</button></ViewTitle><div className="hrx-metric-grid"><MetricCard icon="briefcase" label="Total de Projetos" value={projects.length} tone="blue" note="Registros operacionais"/><MetricCard icon="check" label="Em andamento" value={activeProjects.length - blocked.length} tone="green" note="Fluxos ainda abertos"/><MetricCard icon="warning" label="Bloqueados" value={blocked.length} tone="orange" note="Solicitações suspensas"/><MetricCard icon="check" label="Concluídos" value={completed.length} tone="purple" note="Aprovados ou encerrados"/></div><FilterBar query={query} setQuery={setQuery} placeholder="Buscar projetos…"><select value={statusFilter} onChange={(e) => setStatusFilter(e.target.value)}><option value="all">Todos os status</option><option value="received">Em andamento</option><option value="awaiting_review">Em validação</option><option value="needs_scope">Atenção</option><option value="suspended">Bloqueado</option><option value="approved">Concluído</option></select><select value={priorityFilter} onChange={(e) => setPriorityFilter(e.target.value)}><option value="all">Todas as prioridades</option><option>Alta</option><option>Média</option><option>Baixa</option></select><select value={clientFilter} onChange={(e) => setClientFilter(e.target.value)}><option value="all">Todos os clientes</option>{clients.map((client) => <option value={client.id} key={client.id}>{client.company || client.name}</option>)}</select></FilterBar><section className="hrx-data-table"><div className="hrx-table-header hrx-project-columns"><span>Projeto</span><span>Cliente</span><span>Status</span><span>Prioridade</span><span>Progresso</span><span>Próximo Marco</span><span>Atualização</span><span/></div>{visible.map((project) => <button className={`hrx-table-row hrx-project-columns${selected?.id === project.id ? ' is-selected' : ''}`} type="button" key={project.id} onClick={() => onSelect(project)}><span className="hrx-name-cell"><i className="hrx-row-icon tone-blue"><Icon name="briefcase"/></i><span><strong>{project.protocol}</strong><small>{project.request_text || 'Solicitação operacional'}</small></span></span><span>{project.company || project.name}</span><Badge status={project.status}/><span><Badge status={project.priority === 'Alta' ? 'danger' : project.priority === 'Média' ? 'warning' : 'info'} label={project.priority}/></span><span className="hrx-progress-cell">{project.progress === null ? <small>Não informado</small> : <><b>{project.progress}%</b><i><em style={{ width: `${project.progress}%` }}/></i></>}</span><span><strong>{project.milestone}</strong><small>{project.desired_deadline || 'Prazo não informado'}</small></span><span>{formatDate(project.draft?.updated_at || project.created_at, true)}</span><Icon name="more" size={18}/></button>)}{!visible.length && <Empty icon="briefcase" title="Nenhum projeto encontrado." text="A tela não preenche registros fictícios."/>}</section>{selected && <ProjectDrawer project={selected} onClose={onClose} onOpen={onOpenCommercial}/>}</section>
}
function ProjectDrawer({ project, onClose, onOpen }: { project: ProjectRow; onClose: () => void; onOpen: () => void }) { return <aside className="hrx-detail-drawer"><button className="hrx-drawer-close" onClick={onClose}>×</button><div className="hrx-drawer-title"><span className="hrx-row-icon tone-blue"><Icon name="briefcase"/></span><div><h2>{project.protocol}</h2><p>{project.company || project.name}</p></div></div><Badge status={project.status}/><section><span>Progresso geral</span>{project.progress === null ? <strong>Não informado na base atual</strong> : <div className="hrx-drawer-progress"><strong>{project.progress}%</strong><i><em style={{ width: `${project.progress}%` }}/></i></div>}</section><section><span>Próximo marco</span><strong>{project.milestone}</strong><small>{project.desired_deadline || 'Prazo não informado'}</small></section><section><span>Linha do tempo</span><ol><li className="is-done"><i/><div><strong>Solicitação registrada</strong><small>{formatDate(project.created_at, true)}</small></div></li>{project.draft?.updated_at && <li><i/><div><strong>{statusLabels[project.status] || project.status}</strong><small>{formatDate(project.draft.updated_at, true)}</small></div></li>}</ol></section><section><span>Responsável</span><strong>{project.name}</strong><small>{project.email || 'Contato não informado'}</small></section>{project.status === 'suspended' && <section><span>Risco aberto</span><strong>{project.draft?.suspension_reason || 'Solicitação suspensa'}</strong><small>{project.draft?.suspension_note || 'Sem detalhe adicional'}</small></section>}<footer><button className="hrx-primary-button" onClick={onOpen}>Abrir projeto</button></footer></aside> }
function FilterBar({ query, setQuery, placeholder, children }: { query: string; setQuery: (value: string) => void; placeholder: string; children?: ReactNode }) { return <div className="hrx-filterbar"><label><Icon name="search"/><input value={query} onChange={(event) => setQuery(event.target.value)} placeholder={placeholder}/></label>{children}<button type="button"><Icon name="filter"/>Filtros</button></div> }

function ActivitiesView({ activities, allActivities, projects, blocked, activityTab, setActivityTab }: { activities: ActivityRow[]; allActivities: ActivityRow[]; projects: ProjectRow[]; blocked: ProjectRow[]; activityTab: string; setActivityTab: (value: string) => void }) { return <section className="hrx-view hrx-activities-view" aria-labelledby="activities-title"><ViewTitle id="activities-title" title="Atividades em andamento" description="Eventos operacionais gerados por solicitações e documentos reais."><time><Icon name="calendar" size={18}/>{new Date().toLocaleDateString('pt-BR')}</time></ViewTitle><div className="hrx-metric-grid"><MetricCard icon="check" label="Em andamento" value={allActivities.filter((item) => item.status === 'progress').length} tone="blue" note="Fluxos abertos"/><MetricCard icon="lock" label="Bloqueadas" value={allActivities.filter((item) => item.status === 'blocked').length} tone="orange" note="Itens suspensos"/><MetricCard icon="clock" label="Em validação" value={allActivities.filter((item) => item.status === 'validation').length} tone="purple" note="Aguardando revisão"/><MetricCard icon="check" label="Concluídas" value={allActivities.filter((item) => item.status === 'complete').length} tone="green" note="Eventos finalizados"/></div><div className="hrx-activities-layout"><div className="hrx-activity-workspace"><div className="hrx-tabs">{[['all','Todas'],['progress','Em andamento'],['blocked','Bloqueadas'],['validation','Em validação'],['complete','Concluídas']].map(([value,label]) => <button key={value} type="button" className={activityTab === value ? 'is-active' : ''} onClick={() => setActivityTab(value)}>{label}</button>)}<button className="hrx-tabs-filter"><Icon name="filter"/>Filtros</button></div><div className="hrx-kanban"><ActivityColumn title="Hoje" items={activities.filter((item) => sameDay(item.at))}/><ActivityColumn title="Esta semana" items={activities.filter((item) => thisWeek(item.at) && !sameDay(item.at)).slice(0,8)}/><ActivityColumn title="Bloqueadas" items={activities.filter((item) => item.status === 'blocked')}/></div></div><aside className="hrx-activity-side"><NextSteps projects={projects.slice(0,6)}/><section className="hrx-glass-panel"><header><h2>Bloqueios</h2></header><div className="hrx-block-list">{blocked.map((project) => <article key={project.id}><Icon name="warning"/><div><strong>{project.draft?.suspension_reason || project.milestone}</strong><small>{project.company || project.name}</small><p>{project.draft?.suspension_note || 'Sem detalhe adicional.'}</p></div></article>)}{!blocked.length && <Empty title="Nenhum bloqueio ativo." compact/>}</div></section></aside></div></section> }
function ActivityColumn({ title, items }: { title: string; items: ActivityRow[] }) { return <section><header><h2>{title}</h2><span>{items.length}</span></header>{items.map((item) => <article key={item.id} className={`tone-${item.status}`}><span className="hrx-row-icon"><Icon name={item.status === 'blocked' ? 'warning' : item.kind === 'document' ? 'file' : 'check'}/></span><div><strong>{item.title}</strong><small>{item.context}</small>{item.detail && <p>{item.detail}</p>}<footer><Badge status={item.priority === 'Alta' ? 'danger' : item.priority === 'Média' ? 'warning' : 'info'} label={item.priority}/><time>{formatDate(item.at, true)}</time></footer></div></article>)}{!items.length && <Empty title={`Nenhuma atividade em ${title.toLocaleLowerCase('pt-BR')}.`} compact/>}</section> }

function ClientsView({ clients, visible, requests, selected, onSelect, onClose, onNew, onQuote, query, setQuery }: { clients: ClientRow[]; visible: ClientRow[]; requests: RequestRow[]; selected: ClientRow | null; onSelect: (item: ClientRow) => void; onClose: () => void; onNew: () => void; onQuote: (id: string) => void; query: string; setQuery: (value: string) => void }) { return <section className={`hrx-view hrx-table-view${selected ? ' has-drawer' : ''}`} aria-labelledby="clients-title"><ViewTitle id="clients-title" title="Clientes" description="Carteira real, contatos e histórico comercial."><button className="hrx-primary-button" onClick={onNew}><Icon name="plus"/>Novo cliente</button></ViewTitle><div className="hrx-metric-grid"><MetricCard icon="users" label="Total de Clientes" value={clients.length} tone="blue" note="Cadastros na carteira"/><MetricCard icon="check" label="Ativos" value={clients.filter((item) => item.active).length} tone="green" note="Relacionamentos ativos"/><MetricCard icon="clock" label="Com orçamento" value={new Set(requests.map((item) => item.client_id).filter(Boolean)).size} tone="purple" note="Histórico comercial"/><MetricCard icon="warning" label="Inativos" value={clients.filter((item) => !item.active).length} tone="orange" note="Cadastros inativos"/></div><FilterBar query={query} setQuery={setQuery} placeholder="Buscar clientes…"/><section className="hrx-data-table"><div className="hrx-table-header hrx-client-columns"><span>Cliente</span><span>Contato</span><span>Documento</span><span>Status</span><span>Último orçamento</span><span>Atualização</span><span/></div>{visible.map((client) => <button className={`hrx-table-row hrx-client-columns${selected?.id === client.id ? ' is-selected' : ''}`} key={client.id} onClick={() => onSelect(client)}><span className="hrx-name-cell"><i className="hrx-avatar">{client.name.slice(0,2).toUpperCase()}</i><span><strong>{client.company || client.name}</strong><small>{client.company ? client.name : client.source.replaceAll('_',' ')}</small></span></span><span><strong>{client.email || 'Não informado'}</strong><small>{client.phone || 'Telefone não informado'}</small></span><span>{client.document || 'Não informado'}</span><Badge status={client.active ? 'active' : 'archived'} label={client.active ? 'Ativo' : 'Inativo'}/><span>{formatDate(client.last_quote_at)}</span><span>{formatDate(client.updated_at, true)}</span><Icon name="more" size={18}/></button>)}{!visible.length && <Empty icon="users" title="Nenhum cliente encontrado." text="Cadastre o primeiro cliente ou revise os filtros."/>}</section>{selected && <aside className="hrx-detail-drawer"><button className="hrx-drawer-close" onClick={onClose}>×</button><div className="hrx-drawer-title"><span className="hrx-avatar">{selected.name.slice(0,2).toUpperCase()}</span><div><h2>{selected.company || selected.name}</h2><p>{selected.company ? selected.name : 'Cliente HRX'}</p></div></div><Badge status={selected.active ? 'active' : 'archived'} label={selected.active ? 'Ativo' : 'Inativo'}/><section><span>Contato</span><strong>{selected.email || 'E-mail não informado'}</strong><small>{selected.phone || 'Telefone não informado'}</small></section><section><span>Documento</span><strong>{selected.document || 'Não informado'}</strong><small>Origem: {selected.source.replaceAll('_',' ')}</small></section>{selected.notes && <section><span>Observações</span><p>{selected.notes}</p></section>}<section><span>Histórico comercial</span><strong>{requests.filter((item) => item.client_id === selected.id).length} orçamento(s)</strong><small>Último: {formatDate(selected.last_quote_at)}</small></section><footer><button className="hrx-primary-button" onClick={() => onQuote(selected.id)}>Novo orçamento</button></footer></aside>}</section> }

function DocumentsView({ documents, visible, clients, selected, onSelect, onClose, onOpen, onShare, uploading, onUpload, query, setQuery, clientFilter, setClientFilter, categoryFilter, setCategoryFilter, statusFilter, setStatusFilter }: { documents: DocumentRow[]; visible: DocumentRow[]; clients: ClientRow[]; selected: DocumentRow | null; onSelect: (item: DocumentRow) => void; onClose: () => void; onOpen: (item: DocumentRow, download?: boolean) => Promise<void>; onShare: (item: DocumentRow) => Promise<void>; uploading: boolean; onUpload: () => void; query: string; setQuery: (value: string) => void; clientFilter: string; setClientFilter: (value: string) => void; categoryFilter: string; setCategoryFilter: (value: string) => void; statusFilter: string; setStatusFilter: (value: string) => void }) { const recent = documents.filter((item) => isRecent(item.updated_at || item.created_at)); return <section className={`hrx-view hrx-documents-view hrx-table-view${selected ? ' has-drawer' : ''}`} aria-labelledby="documents-title"><ViewTitle id="documents-title" title="Central de Documentos" description="Hub empresarial para organizar, acessar e compartilhar documentos com segurança."><button className="hrx-primary-button" type="button" onClick={onUpload} disabled={uploading}><Icon name={uploading ? 'clock' : 'plus'}/>{uploading ? 'Enviando…' : 'Novo documento'}</button></ViewTitle><div className="hrx-metric-grid"><MetricCard icon="file" label="Documentos" value={documents.length} tone="blue" note="Registros ativos"/><MetricCard icon="check" label="Atualizados esta semana" value={recent.length} tone="green" note="Últimos 7 dias"/><MetricCard icon="users" label="Clientes" value={new Set(documents.map((item) => item.client_name).filter(Boolean)).size} tone="purple" note="Com documentos vinculados"/><MetricCard icon="warning" label="Pendências" value={documents.filter((item) => item.expires_at && new Date(item.expires_at) < new Date()).length} tone="orange" note="Documentos vencidos"/></div><nav className="hrx-doc-categories" aria-label="Categorias documentais">{categoryOptions.slice(0,6).map(([key,label]) => <button type="button" key={key} className={categoryFilter === key ? 'is-active' : ''} onClick={() => setCategoryFilter(categoryFilter === key ? 'all' : key)}><Icon name="file" size={17}/><span>{label}</span><b>{documents.filter((item) => item.area_key === key).length}</b></button>)}</nav><FilterBar query={query} setQuery={setQuery} placeholder="Buscar documentos…"><select value={clientFilter} onChange={(e) => setClientFilter(e.target.value)}><option value="all">Todos os clientes</option>{clients.map((client) => <option key={client.id} value={client.id}>{client.company || client.name}</option>)}</select><select value={categoryFilter} onChange={(e) => setCategoryFilter(e.target.value)}><option value="all">Todas as categorias</option>{categoryOptions.map(([key,label]) => <option key={key} value={key}>{label}</option>)}</select><select value={statusFilter} onChange={(e) => setStatusFilter(e.target.value)}><option value="all">Todos os status</option><option value="active">Ativo</option><option value="superseded">Substituído</option></select></FilterBar><section className="hrx-data-table"><div className="hrx-table-header hrx-document-columns"><span>Nome do documento</span><span>Cliente/Projeto</span><span>Categoria</span><span>Versão</span><span>Data</span><span>Status</span><span>Ações</span></div>{visible.map((document) => <button className={`hrx-table-row hrx-document-columns${selected?.id === document.id ? ' is-selected' : ''}`} key={document.id} onClick={() => onSelect(document)}><span className="hrx-name-cell"><i className="hrx-file-type">{document.document_type || 'DOC'}</i><span><strong>{document.title}</strong><small>{formatBytes(document.size_bytes)}</small></span></span><span><strong>{document.client_name || 'HRX Solutions'}</strong><small>{document.folder}</small></span><span><Badge status="info" label={areaLabels[document.area_key] || document.area_key}/></span><span>V{document.version}</span><span>{formatDate(document.updated_at || document.created_at, true)}</span><Badge status={document.status}/><span className="hrx-row-actions"><i onClick={(event) => { event.stopPropagation(); void onOpen(document) }}><Icon name="eye" size={17}/></i><i onClick={(event) => { event.stopPropagation(); void onOpen(document, true) }}><Icon name="download" size={17}/></i><i><Icon name="more" size={17}/></i></span></button>)}{!visible.length && <Empty icon="file" title="Nenhum documento encontrado." text="Revise os filtros ou envie um documento para a categoria selecionada."/>}</section>{selected && <aside className="hrx-detail-drawer hrx-document-drawer"><button className="hrx-drawer-close" onClick={onClose}>×</button><h2>{selected.title}</h2><div className="hrx-file-preview"><i>{selected.document_type || 'DOC'}</i><strong>{selected.title}</strong><small>{selected.document_type || 'Arquivo'} · {formatBytes(selected.size_bytes)}</small></div><div className="hrx-drawer-tabs"><button className="is-active">Detalhes</button></div><dl><div><dt>Cliente/Projeto</dt><dd>{selected.client_name || 'HRX Solutions'}<small>{selected.folder}</small></dd></div><div><dt>Categoria</dt><dd>{areaLabels[selected.area_key] || selected.area_key}</dd></div><div><dt>Versão</dt><dd>{selected.version}</dd></div><div><dt>Status</dt><dd><Badge status={selected.status}/></dd></div><div><dt>Data</dt><dd>{formatDate(selected.updated_at || selected.created_at, true)}</dd></div><div><dt>Acesso</dt><dd>{selected.access_class}</dd></div></dl><footer><button className="hrx-primary-button" onClick={() => void onOpen(selected)}><Icon name="eye" size={17}/>Visualizar</button><button onClick={() => void onOpen(selected, true)}><Icon name="download" size={17}/>Baixar</button>{typeof navigator.share === 'function' && <button onClick={() => void onShare(selected)}><Icon name="share" size={17}/>Compartilhar</button>}</footer></aside>}</section> }

function SettingsView({ initials, userName, email, userRole, password, setPassword, confirmPassword, setConfirmPassword, busy, message, onSubmit }: { initials: string; userName: string; email: string; userRole: string; password: string; setPassword: (value: string) => void; confirmPassword: string; setConfirmPassword: (value: string) => void; busy: boolean; message: string; onSubmit: (event: FormEvent) => void }) { return <section className="hrx-view hrx-settings-view" aria-labelledby="settings-title"><ViewTitle id="settings-title" title="Configurações" description="Perfil, segurança e preferências disponíveis no ambiente atual."/><div className="hrx-settings-layout"><nav><button className="is-active"><Icon name="users"/><span><strong>Perfil</strong><small>Conta administrativa</small></span></button><button><Icon name="lock"/><span><strong>Segurança</strong><small>Senha e MFA</small></span></button></nav><div><section className="hrx-settings-card"><header><span className="hrx-avatar">{initials}</span><div><h2>{userName}</h2><p>{email || 'Sessão administrativa'}</p></div></header><dl><div><dt>Perfil</dt><dd>{userRole}</dd></div><div><dt>Ambiente</dt><dd>HRX Admin PWA</dd></div><div><dt>Proteção</dt><dd>MFA obrigatório</dd></div></dl></section><form className="hrx-settings-card" onSubmit={onSubmit}><h2>Alterar senha</h2><p>{passwordRequirementText}</p><label>Nova senha<input type="password" minLength={12} value={password} onChange={(event) => setPassword(event.target.value)} autoComplete="new-password"/></label><label>Confirmar nova senha<input type="password" minLength={12} value={confirmPassword} onChange={(event) => setConfirmPassword(event.target.value)} autoComplete="new-password"/></label>{confirmPassword && password !== confirmPassword && <span className="hrx-inline-warning">As senhas precisam ser iguais.</span>}{message && <span className="hrx-inline-message">{message}</span>}<button className="hrx-primary-button" disabled={busy || !passwordMeetsPolicy(password) || password !== confirmPassword}>{busy ? 'Validando…' : 'Salvar nova senha'}</button></form></div></div></section> }
